import bisect

class Solution:
    def answerQueries(self, nums: list[int], queries: list[int]) -> list[int]:
        nums.sort()
        pref = []
        cur = 0
        for x in nums:
            cur += x
            pref.append(cur)
        return [bisect.bisect_right(pref, q) for q in queries]

class Solution {
public:
    std::vector<int> answerQueries(std::vector<int>& nums, std::vector<int>& queries) {
        std::sort(nums.begin(), nums.end());
        std::vector<int> pref(nums.size());
        int cur = 0;
        for (int i = 0; i < (int)nums.size(); i++) {
            cur += nums[i];
            pref[i] = cur;
        }
        std::vector<int> ans;
        ans.reserve(queries.size());
        for (int q : queries) {
            int idx = std::upper_bound(pref.begin(), pref.end(), q) - pref.begin();
            ans.push_back(idx);
        }
        return ans;
    }
};

class Solution {
    public int[] answerQueries(int[] nums, int[] queries) {
        java.util.Arrays.sort(nums);
        int[] pref = new int[nums.length];
        int cur = 0;
        for (int i = 0; i < nums.length; i++) {
            cur += nums[i];
            pref[i] = cur;
        }
        int[] ans = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int q = queries[i];
            int l = 0, r = pref.length;
            while (l < r) {
                int mid = (l + r) / 2;
                if (pref[mid] <= q) l = mid + 1;
                else r = mid;
            }
            ans[i] = l;
        }
        return ans;
    }
}

var answerQueries = function(nums, queries) {
    nums.sort((a, b) => a - b);
    const pref = [];
    let cur = 0;
    for (const x of nums) {
        cur += x;
        pref.push(cur);
    }
    return queries.map(q => {
        let l = 0, r = pref.length;
        while (l < r) {
            const mid = Math.floor((l + r) / 2);
            if (pref[mid] <= q) l = mid + 1;
            else r = mid;
        }
        return l;
    });
};
